void ClipboardHostAsyncWaiter::GetClipContent(
    ClipDataPtr* out_data) {
  base::RunLoop loop;
  proxy_->GetClipContent(
      base::BindOnce(
          [](base::RunLoop* loop,
             ClipDataPtr* out_data
,
             ClipDataPtr data) {*out_data = std::move(data);
            loop->Quit();
          },
          &loop,
          out_data));
  loop.Run();
}

